List<Integer> computeUpperBounds(List<K> keys) {
    // Initialize the upper bounds to the maximum value
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        upperBounds.add(Integer.MAX_VALUE);
    }

    // Compute the upper bounds for each key
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        int upperBound = 0;
        for (int j = i + 1; j < keys.size(); j++) {
            if (keys.get(j).compareTo(key) > 0) {
                upperBound = Math.max(upperBound, keys.get(j).compareTo(key));
            }
        }
        upperBounds.set(i, upperBound);
    }

    return upperBounds;
}
