public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("Thread")) {
                String[] parts = line.split("\\s+");
                long threadId = Long.parseLong(parts[1]);
                String threadName = parts[2];
                String groupName = parts[3];
                int depth = Integer.parseInt(parts[4]);
                Map<Integer, ThreadEvent> threadIdToThreadEvent = new HashMap<>();
                StackTrace stackTrace = new StackTrace();
                List<ThreadEvent> threadHistory = new ArrayList<>();
                Map<HprofData.StackTrace, int[]> stackTraces = new HashMap<>();
                long startMillis = 0;
                int flags = 0;
                int stackTraceId = 0;
                int count = 0;
                while ((line = reader.readLine()) != null) {
                    if (line.startsWith("StackTrace")) {
                        String[] parts = line.split("\\s+");
                        stackTraceId = Integer.parseInt(parts[1]);
                        stackFrames = new StackTraceElement[Integer.parseInt(parts[2])];
                        for (int i = 0; i < stackFrames.length; i++) {
                            String[] frameParts = reader.readLine().split("\\s+");
                            stackFrames[i] = new StackTraceElement(frameParts[0], frameParts[1], frameParts[2], Integer.parseInt(frameParts[3]));
                        }
                    } else if (line.startsWith("ThreadEvent")) {
                        String[] parts = line.split("\\s+");
                        int threadEventType = Integer.parseInt(parts[1]);
                        long startMillis = Long.parseLong(parts[2]);
                        int flags = Integer.parseInt(parts[3]);
                        String parentGroupName = parts[4];
                        String threadName = parts[5];
                        int threadId = Integer.parseInt(parts[6]);
                        String groupName = parts[7];
                        int depth = Integer.parseInt(parts[8]);
                        ThreadEvent threadEvent = new ThreadEvent(threadEventType, startMillis, flags, parentGroupName, threadName, threadId, groupName, depth);
                        threadIdToThreadEvent.put(threadId, threadEvent);
                        threadHistory.add(threadEvent);
                        stackTrace.addStackTrace(threadEvent);
                        stackTraces.put(new HprofData.StackTrace(stackTraceId, stackFrames), new int[stackFrames.length]);
                    } else if (line.startsWith("Sample")) {
                        String[] parts = line.split("\\s+");
                        int sampleCount = Integer.parseInt(parts[1]);
                        long sampleMillis = Long.parseLong(parts[2]);
                        int threadId = Integer.parseInt(parts[3]);
                        ThreadEvent threadEvent = threadIdToThreadEvent.get(threadId);
                        if (threadEvent != null) {
                            threadEvent.addSample(sampleCount, sampleMillis);
                        }
                    }
                }
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, threadName, groupName, depth, threadHistory, stackTrace, stackTraces);
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    return threadSnapshots;
}
